        src = item["path"]
        festival = item["festival"]
        dst = destination + "/" + src
        if dst in file_by_path:
            raise ValueError("destination already exists")
        moves.append({"from": src, "to": dst, "festival": festival})

    moves.sort(key=lambda m: (m["from"], m["to"]))

