class TestOutbox(unittest.TestCase):
    def test_transform_shape_and_business(self):
        snapshot = {
            "recipient": "friend47",
            "destination": "holiday",
            "festivals": ["spring", "summer", "winter"],
            "files": [{"path": "photos/day0/img.jpg", "hex": "00"}],
            "photos": [{"path": "photos/day0/img.jpg", "festival": "spring"}],
        }
